function renderBusiness(){
 const b=bizById(route.id);if(!accessibleRecord(b))return unavailable();const p=image(b.photos?.[0]),unclaimed=b.claimed===false,susp=!!b.suspended;
 actionsBar(`${iconBtn(b.saved?'bookmark':'bookmark_border','save-biz',b.id,b.saved?'Remover negócio dos salvos':'Salvar negócio',`aria-pressed="${!!b.saved}"`)}${iconBtn('share','share',`negocio|${b.id}`,'Compartilhar negócio')}${b.mine?`${btn('Editar página','edit-biz',b.id,'filled','edit')}${iconBtn('more_vert','biz-menu',b.id,'Opções da página')}`:susp?'':unclaimed?btn(b.myInd?'Convidar responsável':'Também indico',b.myInd?'invite-owner':'recommend-biz',b.id,'filled',b.myInd?'send':'thumb_up'):btn('Pedir orçamento','quote',b.id,'filled','request_quote')}`);
 const asks=state.asks.filter(q=>!q.hidden&&!q.hiddenByMe&&(q.mine||!isBlocked(q.who))&&q.city===b.city&&q.answers.some(a=>a.biz===b.id));
 let h=`<div class="detail-layout"><div><div class="detail-hero">${p?`<img src="${p}" alt="${esc(b.name)}"><button type="button" class="hero-zoom" data-action="lightbox" data-value="biz">${icon('image')}Ver foto</button>`:''}<span class="pill">${esc(isSpon(b)?'Patrocinado':b.cat)}</span></div>${b.demo?'<p class="labelled-example">Foto ilustrativa do negócio de exemplo.</p>':''}<div class="detail-title"><h1>${esc(b.name)}</h1><p class="small muted">${esc(b.cat)}${b.specs?.length?` · ${esc(b.specs.join(', '))}`:''} · ${esc(b.city)}</p></div>${susp?`<div class="context-strip readonly" style="margin-top:0" role="status">${icon('lock')}<span class="grow"><b>Página suspensa pela moderação</b><br>Ela não aparece no catálogo nem na busca, e não recebe pedidos.</span></div>`:''}${b.mine&&b.paused?pausedStrip(b):''}${unclaimed?`<div class="context-strip readonly" style="margin-top:0">${icon('hourglass_top')}<span>Esta página foi indicada por um membro. O responsável ainda não confirmou as informações.</span></div>`:''}${b.disc?`<div class="business-benefit">${icon('sell')} <b>Benefício para a comunidade</b><br>${esc(b.disc)}</div>`:''}<section class="section">${sectionTitle('Como pode ajudar')}<p class="detail-copy">${esc(b.bio||'O responsável poderá completar a descrição quando assumir a página.')}</p></section><section class="section">${sectionTitle('Serviços')}<md-chip-set>${b.svc.map(s=>`<md-assist-chip label="${esc(s)}">${icon('check','icon')}</md-assist-chip>`).join('')}</md-chip-set>${!b.svc.length?'<p class="small muted">Serviços ainda não informados pelo responsável.</p>':''}</section><section class="section">${sectionTitle('Onde atende')}<md-chip-set>${b.hoods.map(s=>`<md-assist-chip label="${esc(s)}">${icon('location_on','icon')}</md-assist-chip>`).join('')}</md-chip-set></section><section class="section">${sectionTitle('O que a comunidade diz')}<div class="stack">${(b.says||[]).map(x=>`<div class="answer"><div class="row"><span class="avatar">${esc(x[0])}</span><b>${esc(x[2])}</b></div><p>${esc(x[3])}</p></div>`).join('')||'<p class="small muted">Os relatos aparecem quando um membro indica este negócio.</p>'}</div></section>${asks.length?`<section class="section">${sectionTitle('Ver a origem das indicações')}<div class="list">${asks.map(questionRow).join('')}</div></section>`:''}</div><aside class="detail-aside"><div class="facts" style="grid-template-columns:1fr 1fr"><div class="fact fact-proof">${countHtml(b.recN)}<span>indicações da comunidade</span>${avatarStack(b.says,b.recN||0)}</div><div class="fact">${icon('schedule')}<span>${esc(b.hours||'Confirme com o responsável')}</span></div></div>${b.owner?`<div class="seller">${icon('verified_user')}<span class="small grow">${esc(b.owner)}</span>${iconBtn('info','verified-info','','O que o selo “verificado” significa','aria-haspopup="dialog"')}</div>`:''}${b.mine?businessMetrics(b):`<div class="stack">${!unclaimed&&!susp&&b.whatsapp?btn('WhatsApp','whatsapp',b.id,'outlined','call'):''}${!unclaimed&&!susp&&b.instagram?btn('Instagram','instagram',b.id,'outlined'):''}${!unclaimed&&!susp&&b.website?btn('Site','website',b.id,'outlined','open_in_new'):''}${susp?'':unclaimed?btn('Sou o responsável','claim-biz',b.id,'outlined','storefront'):btn('Indicar este negócio','recommend-biz',b.id,'outlined','thumb_up')}${btn('Denunciar página','report',`biz|${b.id}`,'text','flag')}</div>`}</aside></div>`;return h;
}
// Rodada 61 (maquete quadro 12): pausar tira a página do catálogo, da busca, das sugestões e das propostas
// para pedidos novos. Pausada não é suspensa: a suspensão é do Painel (R60) e só o Painel a reverte.
// A frase de apoio do item fica curta: o popover não quebra linha. A frase completa da maquete vai na faixa.
const BIZ_PAUSE_NOTE='Sai da busca e do catálogo';
function pausedStrip(b){return `<div class="context-strip readonly" style="margin-top:0" role="status">${icon('visibility_off')}<span class="grow"><b>Página pausada</b><br>Pausada, a página sai da busca e do catálogo; você reativa quando quiser.</span>${btn('Reativar','resume-biz',b.id,'text','visibility')}</div>`;}
// Menu ⋮ da minha página (quadro 12) e as ações Pausar, Reativar e Excluir.
function ownBizAction(action,value,el){
 const b=state.myBiz;if(!b?.live||b.id!==value)return;
 if(action==='biz-menu'){openCreate(el,[['edit','Editar página','edit-biz','',value],[b.paused?'visibility':'visibility_off',b.paused?'Reativar página':'Pausar página',b.paused?'resume-biz':'pause-biz',b.paused?'':BIZ_PAUSE_NOTE,value],['delete','Excluir página','delete-biz','',value,true]]);return;}
 if(action==='pause-biz'||action==='resume-biz'){const pause=action==='pause-biz';if(!mutate(()=>{b.paused=pause;}))return;notify(pause?'Página pausada. Ela saiu da busca e do catálogo.':'Página reativada. Ela voltou ao catálogo e à busca.',pause?'visibility_off':'visibility');return;}
 if(action==='delete-biz')confirm('Excluir página?','A página sai do Bivaque. As propostas abertas saem dos pedidos e os clientes deixam de vê-las. Isso não pode ser desfeito.',()=>deleteMyBiz(value),{ok:'Excluir',cancel:'Cancelar',danger:true});
}
// Excluir: a página some; propostas abertas viram retiradas, e o histórico de pedidos concluídos fica como está.
// Rodada 65: as recusadas de pedido ainda aberto ou escolhido também saem (não voltam num "desistir"); o
// patrocínio acaba com a página; a suspensão do Painel fica na conta (`bizSuspended`) e vale na página nova.
function bizLeaveRequests(id){for(const r of requestList())for(const p of r.proposals)if(p.bizId===id&&(p.status==='sent'||p.status==='declined'&&['open','chosen'].includes(r.status)))p.status='withdrawn';}
function deleteMyBiz(id){
 if(state.myBiz?.id!==id)return;
 if(!mutate(()=>{bizLeaveRequests(id);if(state.myBiz.suspended)state.bizSuspended=true;if(state.subscription)delete state.subscription.spot;state.myBiz=null;},{redraw:false}))return;
 navigate('voce',null,{replace:true});notify('Página excluída. As propostas abertas saíram dos pedidos.','delete');
}
function businessMetrics(b){const ts=state.threads.filter(t=>t.about.type==='biz'&&t.about.id===b.id);return `<section class="section" style="margin-top:16px">${sectionTitle('Resultados da sua página')}<div class="metric-grid"><div class="metric"><b>${b.views||0}</b><span>visitas</span></div><div class="metric"><b>${ts.length}</b><span>pedidos de contato</span></div><div class="metric"><b>${ts.filter(t=>t.msgs.some(m=>m.me)).length}</b><span>conversas respondidas</span></div></div><p class="small muted" style="margin-top:12px">Plano ${state.subscription.tier==='free'?'grátis':'de teste'} · os indicadores contam as ações realizadas nesta versão.</p>${planStatusHtml()}<div class="stack" style="margin-top:16px">${btn('Ver pedidos recebidos','biz-leads',b.id,'outlined','inbox')}${btn('Conhecer os planos','plans','','tonal','trending_up')}${btn('Copiar link da página','share',`negocio|${b.id}`,'text','link')}</div></section>`;}
